from pathlib import Path
import base64, gzip

ROOT = Path("resmi-gazete-app")
FILES = {
'app/src/main/java/com/hakim/resmigazeteozeti/MainActivity.java': '',
'app/src/main/res/values/styles.xml': '',
'app/build.gradle.kts': '',
'README_TR.md': '',
}
for relative, payload in FILES.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(payload)))
print("Resmî Gazete Özeti v1.1.0 kaynak düzeltmeleri uygulandı.")
